
import PLAN from '../../../../packages/shared/src/psw-personal/catalog.json';
import {seedPersonal as seed} from '../../../../packages/shared/src/psw-personal/core.mjs';
import {renderCare} from '../care/dashboard';
export async function renderPersonalView(root,gateway,initial,api){
let meta=initial;const synthetic=meta.synthetic;const NAME=meta.profile.name,INITIALS=NAME.split(/\s+/).slice(0,2).map(s=>s[0]).join('');
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const ICONS={today:'M3 10 9-7 9 7v11h-6v-7H9v7H3Z',schedule:'M8 2v4m8-4v4M3 10h18M5 4h14v17H3V4Z',visit:'M9 4H5v17h14V4h-4M9 2h6v5H9Zm-2 10 2 2 4-4m-6 8h10',hours:'M12 8v5l3 2m6-3a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',pay:'M3 6h18v14H3Zm0 5h18m-6 5h3',availability:'M8 2v4m8-4v4M3 10h18M5 4h14v17H3V4Zm3 11 3 3 5-6',messages:'M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 1 1 20 0Z',profile:'M20 21v-2a7 7 0 0 0-14 0v2m10-14a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',questions:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',guide:'m5 12 4 4L19 6',plan:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z'};const icon=n=>`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.guide}"/></svg>`;
const BASE=initial.today,MON=initial.from;const nav=[['today','My day'],['schedule','My schedule'],['visit','My visits & tasks'],['hours','My hours'],['pay','Pay & expenses'],['availability','Availability & leave'],['messages','Messages & help'],['profile','Profile & readiness'],['questions','PSW questions'],['guide','Getting started'],['plan','Tasks & registration']];
const tasks=['Confirm consent and read the assigned plan','Support the agreed personal-care routine','Offer planned mobility support','Leave the space comfortable and record handover'];
let state=structuredClone(initial.state),savedState=structuredClone(initial.state),version=initial.version,pending=false;let page=location.hash.slice(1)||'today',selectedDate=BASE,week=MON,qaFilter='',qaGroup='all',toastTimer;const app=root;const visit=id=>state.visits.find(v=>v.id===id),hours=n=>(n/60).toFixed(2),net=t=>Math.max(0,t.gross-t.break),sum=(a,f)=>a.reduce((n,x)=>n+f(x),0),add=(d,n)=>new Date(Date.parse(d+'T12:00:00Z')+n*864e5).toISOString().slice(0,10),clock=s=>new Date('2026-10-28T'+s+':00').toLocaleTimeString('en-CA',{hour:'numeric',minute:'2-digit'}),label=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-CA',{weekday:'short',month:'short',day:'numeric'});const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);const badge=s=>`<span class="badge ${['pending','submitted','assigned','requested','returned'].includes(s)?'amber':s==='cancelled'?'red':s==='in_progress'?'blue':''}">${E(({assigned:'Assigned',accepted:'Accepted',in_progress:'In progress',submitted:'Note submitted',reviewed:'Reviewed',pending:'Awaiting review',returned:'Needs correction',approved:'Approved',requested:'Requested',unread:'Unread',acknowledged:'Acknowledged',cancelled:'Cancelled'})[s]||s)}</span>`;
function toast(s){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el);}el.classList.add('visible');el.textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast')&&(document.getElementById('toast').textContent=''),6000)}
function command(action,detail){
 const v=()=>state.visits.find(v=>v.id===detail),t=()=>state.time.find(t=>t.id===detail);
 if(action==='Visit accepted')return ['accept',{visitId:detail}];
 if(action==='Demo visit started')return ['start',{visitId:detail,consent:true}];
 if(action==='Visit and time submitted'){const id=detail.split(' · ')[0],v=state.visits.find(v=>v.id===id),t=state.time.at(-1);return ['submit',{visitId:id,note:v.note,outcomes:v.outcomes,gross:t.gross,break:t.break,reason:t.reason}];}
 if(action==='Time correction resubmitted')return ['time_correct',{id:detail,gross:t().gross,break:t().break,reason:t().reason}];
 if(action==='Availability goal updated')return ['goal',{goal:state.goal}];
 if(action==='Availability preferences saved')return ['preferences',state.available];
 if(action==='Expense request submitted'){const x=state.expenses[0];return synthetic?['expense',x]:['request',{type:'Expense request',detail:x.date+' · '+x.category+' · '+x.amount+(x.category==='Mileage'?' km':' CAD')+' · '+x.reason+' · Evidence: '+x.evidence}];}
 if(action==='Local message saved'){const x=state.messages[0];return synthetic?['message',{subject:x.subject,message:x.text,to:x.from.replace(/^You → /,'')}]:['request',{type:'Team message',detail:x.subject+' · '+x.text}];}
 if(action==='Update acknowledged')return ['ack',{id:detail}];
 if(action==='Practice reset')return ['demo_clear',{}];
 const x=state.requests[0];if(!x)throw Error('No request to save.');return ['request',{type:x.type,detail:x.detail}];
}
async function commit(action,value){
 if(pending)return toast('Wait for the current database save.');pending=true;draw();
 try{const result=await api.mutate({version,action,value},week);meta=result;state=result.state;savedState=structuredClone(state);version=result.version;pending=false;draw();toast('Saved to PostgreSQL · '+(synthetic?'marked demo data':'your live workspace')+'.');return true;}
 catch(e){state=structuredClone(savedState);pending=false;draw();toast('Not saved: '+e.message+' Refresh before retrying.');return false;}
}
function save(action,detail){try{const [name,value]=command(action,detail);void commit(name,value);}catch(e){state=structuredClone(savedState);draw();toast('Not saved: '+e.message);}}
async function reload(){if(pending)return;try{const next=await api.read(week);meta=next;state=next.state;savedState=structuredClone(state);version=next.version;draw();}catch(e){toast('Refresh failed: '+e.message);}}
async function nativeRecord(id,section){
 const d=document.createElement('dialog');d.style.maxWidth='1100px';d.innerHTML='<header><h2>My authorized care record</h2><button type="button" data-close aria-label="Close care record">Close</button></header><div class="dialog-body"><div data-native-care><p>Loading the existing care workflow…</p></div></div>';document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();};d.oncancel=()=>d.remove();
 const host=d.querySelector('[data-native-care]');let loaded=false;
 const normalize=()=>{host.querySelectorAll('aside,.topbar,.growth-hero').forEach(e=>e.hidden=true);host.querySelectorAll('main > section.section').forEach(e=>{e.hidden=!(section==='staffing'?['care-staffing']:section==='timesheets'?['care-detail','care-timesheets']:['care-detail','care-cases']).includes(e.dataset.cy)});};
 await renderCare(host,gateway,{initialCase:id||undefined,onSnapshot:()=>{normalize();if(loaded)void reload();loaded=true;}});normalize();
 new MutationObserver(normalize).observe(host,{childList:true,subtree:true});
 const old=d.onclose;d.addEventListener('close',()=>void reload());
}
function go(p){page=p;location.hash=p;draw();window.scrollTo(0,0)}
const field=(n,l,v='',type='text',extra='')=>`<label>${E(l)}<input name="${n}" type="${type}" value="${E(v)}" required ${extra}></label>`;const text=(n,l,v='')=>`<label>${E(l)}<textarea name="${n}" required maxlength="2000">${E(v)}</textarea></label>`;const select=(n,l,opts,v)=>`<label>${E(l)}<select name="${n}">${opts.map(([id,label])=>`<option value="${id}" ${v===id?'selected':''}>${E(label)}</option>`).join('')}</select></label>`;
function modal(title,html,submit,fn){const d=document.createElement('dialog');d.innerHTML=`<form><header><h2>${E(title)}</h2><button type="button" data-close aria-label="Close">✕</button></header><div class="dialog-body"><p class="error" role="alert"></p><p class="muted" style="font-size:11px">${synthetic?'Synthetic practice data':'Authorized live care'} · PostgreSQL</p>${html}</div><footer><button type="button" data-close>Close</button>${submit?`<button class="primary" type="submit">${E(submit)}</button>`:''}</footer></form>`;document.body.append(d);d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{d.close();d.remove()});d.oncancel=()=>d.remove();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)));d.close();d.remove()}catch(e){d.querySelector('.error').textContent=e.message}};d.showModal();return d}
function totals(){const t=state.time.filter(t=>t.date>=week&&t.date<=add(week,6)),v=state.visits.filter(v=>v.date>=week&&v.date<=add(week,6)&&v.status!=='cancelled');return{rows:t,planned:sum(v,v=>v.duration),reported:sum(t,net),approved:sum(t.filter(t=>t.status==='approved'),net),pending:sum(t.filter(t=>t.status==='pending'),net),returned:sum(t.filter(t=>t.status==='returned'),net)}}
function stats(items){return `<div class="grid stats">${items.map(([name,val,sub])=>`<article class="card stat"><p class="muted">${name}</p><div class="value">${val}</div><small>${sub}</small></article>`).join('')}</div>`}
function draw(){if(page==='plan'&&!['code_admin','platform_admin','central_admin'].includes(meta.identity.role))page='guide';if(!nav.some(n=>n[0]===page))page='today';const title={today:['MY PERSONAL WORKSPACE',`Welcome, ${E(NAME.split(/\s+/)[0])}.`,'Your visits, your tasks and your hours. Everything you need for the day.'],schedule:['MY ASSIGNED VISITS','A week you can plan around.','Only your own schedule. New work requests need scheduling confirmation.'],visit:['MY CARE WORK','Every task. Every visit.','Follow the assigned plan, record choices and submit factual notes.'],hours:['MY TIME RECORD','Know where every hour stands.','Scheduled, reported, approved and paid are different things.'],pay:['PAY & REIMBURSEMENT','A clear view of what is confirmed.','No invented rates, pay dates or payroll confirmations.'],availability:['MY WORK PREFERENCES','Make your availability visible.','Request time off, publish availability and ask for more work.'],messages:['MY TEAM & SUPPORT','Keep the right people informed.','Read updates, acknowledge changes and track your requests.'],profile:['MY ACCOUNT & READINESS','Ready for the next visit.','Your profile, required documents and access to help.'],questions:['QUESTIONS BEFORE SCREENS','Every PSW question, answered.','A searchable question catalogue linked to tasks, screens and workflows.'],guide:['GETTING STARTED','Your first shift, step by step.','A short guide you can come back to whenever you need it.'],plan:['IMPLEMENTATION BLUEPRINT','From worker questions to working screens.','A proposed screen and workflow map, ready for the integration stage.']}[page];app.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><span class="brandmark">♡</span>PrimeCare</div><div class="caption">My care workspace</div><nav>${nav.filter(([id])=>id!=='plan'||['code_admin','platform_admin','central_admin'].includes(meta.identity.role)).map(([id,name])=>`<button data-go="${id}" class="${page===id?'active':''}">${icon(id)}${name}</button>`).join('')}<a href="/tenant-dashboard?enable-semantics=true" data-cy="tenant-task-sidebar-nav" style="display:block;padding:12px;color:inherit">My work & tasks</a></nav><div class="identity"><span class="avatar">${E(INITIALS)}</span><div><strong>${E(NAME)}</strong><br><small>${E(meta.profile.role.toUpperCase())} · ${synthetic?'marked demo':'my work'}</small></div></div></aside><div><header class="top"><div class="top-left"><button class="mobile" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><span class="top-text">My workspace <span class="muted"> / ${E(nav.find(n=>n[0]===page)[1])}</span></span></div><div class="actions"><span class="badge amber">${synthetic?'DATABASE DEMO':'LIVE · POSTGRESQL'}</span><button data-go="messages" aria-label="Open messages">${icon('messages')} ${state.messages.filter(m=>m.status==='unread').length}</button><span class="avatar">${E(INITIALS)}</span></div></header><main class="main" data-cy="screen-psw-personal-${page}"><div class="heading"><div><div class="caption">${title[0]}</div><h1>${title[1]}</h1><p>${title[2]}</p></div><div class="actions"><button data-go="questions">PSW questions</button><button data-action="help" class="primary">Contact my team</button></div></div><div class="banner"><strong>${synthetic?'MARKED DEMO DATA':'LIVE ACCOUNT DATA'} · ${E(meta.identity.organization)} · v${version}</strong> ${synthetic?'Fictional practice records saved to PostgreSQL. Clear demo data for a fresh practice workspace.':'Your authorized visits, reported time and saved requests. Clinical actions keep the existing care-team rules.'} <button class="linkbutton" data-action="refresh">Refresh saved data</button> · <a href="/psw?experience=personal&dataset=${synthetic?'live':'demo'}">${synthetic?'My live records (PSW account required)':'Practice with demo data'}</a></div>${({today:todayPage,schedule:schedulePage,visit:visitPage,hours:hoursPage,pay:payPage,availability:availabilityPage,messages:messagesPage,profile:profilePage,questions:questionsPage,guide:guidePage,plan:planPage})[page]()}<div class="footer"><span>PrimeCare · PSW personal workspace · Toronto time · ${E(label(week))}–${E(label(add(week,6)))}</span><span><button class="linkbutton" data-action="export">${synthetic?'Export demo':'Export my data'}</button> · ${synthetic?'<button class="linkbutton" data-action="reset">Clear demo data</button> · <button class="linkbutton" data-action="demo_load">Load demo data</button>':''}</span></div></main></div></div>`;bind();if(pending)app.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true)}
function visitRow(v){return `<article class="visit"><div><span class="time">${clock(v.start)}</span><br><small>${hours(v.duration)} h planned${v.endDate&&v.endDate>v.date?'<br>'+E(label(v.date))+' → '+E(label(v.endDate)):''}</small></div><div><h3>${E(v.client)}</h3><p>${E(v.service)} · ${E(v.area)}</p>${badge(v.status)} ${v.ready===false?'<span class="badge red">Plan review needed</span>':''}</div><div class="actions"><button data-visit="${v.id}" ${v.status==='assigned'?'class="primary"':''}>${v.status==='in_progress'?'Continue visit':v.status==='assigned'?'Prepare visit':'Open record'}</button></div></article>`}
const occursOn=(v,day)=>v.date===day||v.date<day&&v.endDate&&(v.endDate>day||v.endDate===day&&v.endTime>'00:00');
function todayPage(){const daily=state.visits.filter(v=>occursOn(v,BASE)),t=state.time.filter(t=>t.date===BASE),next=daily.find(v=>['assigned','accepted','in_progress'].includes(v.status)),all=totals();return `${stats([['Today’s visits',daily.length,'Your assigned visits only'],['Today reported',hours(sum(t,net))+' h','Actual time less unpaid breaks'],['This week approved',hours(all.approved)+' h','Separate from payroll confirmation'],['Needs your attention',state.time.filter(t=>t.status==='returned').length+state.messages.filter(m=>m.status==='unread').length,'Corrections and unread updates']])}<div class="grid two"><div class="grid"><section class="card"><div class="section-head"><h2>Your next visit</h2><span class="badge blue">${E(label(BASE))}</span></div>${next?`<div class="next"><div class="row">${badge(next.status)}<span class="muted">${clock(next.start)} · ${hours(next.duration)} hours planned</span></div><h2>${E(next.client)}</h2><p>${E(next.service)} · ${E(next.area)}</p><p class="muted">Assigned provider: <strong>${E(NAME)} · ${E(meta.profile.role.toUpperCase())}</strong></p><div class="actions" style="margin-top:18px"><button class="primary" data-visit="${next.id}">${next.status==='in_progress'?'Continue my visit':'Read plan & prepare'}</button><button data-issue="${next.id}">Report delay / issue</button></div></div>`:`<p class="empty">${daily.length?'All today’s visits have been submitted.':'No assigned visits on this date.'}</p>`}<div class="section-head"><h3>Today’s timeline</h3><button class="linkbutton" data-go="schedule">Full schedule →</button></div>${daily.map(visitRow).join('')}</section><section class="card"><div class="section-head"><h2>What needs my action?</h2><span class="badge amber">Keep the loop closed</span></div><div class="item"><button class="linkbutton" data-go="hours">${state.time.some(t=>t.status==='returned')?'Review my returned time →':'View my time records →'}</button><p>Original records retained · ${state.time.length?badge(state.time.some(t=>t.status==='returned')?'returned':'pending'):'No time records yet'}</p></div><div class="item"><button class="linkbutton" data-go="messages">Read my team updates →</button><p>Review messages and open care records for current plan readiness.</p></div>${state.requests.filter(r=>r.status==='requested').map(r=>`<div class="item"><strong>${E(r.type)}</strong><p>${E(r.detail)} · awaiting team response</p></div>`).join('')}</section></div><div class="grid"><section class="card board-plan"><span class="badge">MY WEEK · ${E(label(week))}–${E(label(add(week,6)))}</span><h2 style="margin-top:14px">${hours(all.planned)} h scheduled</h2><p>My availability goal: ${state.goal?state.goal+' h':'Not set'} · ${Math.max(0,state.goal-all.planned/60).toFixed(1)} h gap</p><div class="progress"><i style="width:${(state.goal?Math.min(100,all.planned/60/state.goal*100):0)}%"></i></div><p class="goal" style="color:#c8e2e5">A planning goal, not guaranteed work or wages. ${state.goal?'':'Set your goal in Availability.'}</p><button data-go="availability" style="margin-top:18px">Ask for suitable open work</button></section><section class="card"><h2>Before you start</h2><div class="checklist" style="margin-top:18px">${[['1','Read the current assigned plan'],['2','Confirm consent and readiness'],['3','Record tasks and factual outcomes'],['4','Submit actual time and breaks']].map(([n,t])=>`<div><span class="checkmark">${n}</span><span>${t}</span></div>`).join('')}</div><button class="linkbutton" data-go="guide" style="margin-top:20px">Open the first-shift guide →</button></section><section class="card"><h3>Your care team</h3>${synthetic?'<div class="item"><strong>Maya Chen · demo supervisor</strong><p>Plan, task and care concerns</p></div><div class="item"><strong>Rina Ahmed · demo coordinator</strong><p>Scheduling, coverage and time queries</p></div>':meta.team?.length?meta.team.map(p=>`<div class="item"><strong>${E(p.name)}</strong><p>${E(p.role.replaceAll('_',' '))}</p></div>`).join(''):'<p class="muted">No assigned care-team contacts for this week. Use an assigned care record or contact tenant operations.</p>'}<button data-action="help">Contact my team</button><p class="muted" style="font-size:11px;margin-top:12px">Saved request to the in-app team queue. No emergency alert or external message is sent.</p></section></div></div>`}
function schedulePage(){return `<section class="card"><div class="section-head"><h2>My assigned week</h2><label>Choose date<input type="date" id="schedule-date" value="${selectedDate}"></label></div><div class="daystrip">${Array.from({length:7},(_,i)=>{const d=add(week,i);return `<button data-date="${d}" class="${selectedDate===d?'active':''}">${label(d).split(',')[0]}<strong>${d.slice(-2)}</strong>${state.visits.filter(v=>occursOn(v,d)).length} visits</button>`}).join('')}</div><div class="section-head"><h3>${label(selectedDate)}</h3><button data-action="open-work">Request open work</button></div>${state.visits.filter(v=>occursOn(v,selectedDate)).map(visitRow).join('')||'<p class="empty">No assigned visits on this date. Availability does not guarantee an assignment.</p>'}</section>`}
function visitPage(){return `<section class="card"><div class="section-head"><h2>My visits & documentation</h2><span class="badge">Assigned to ${E(NAME)}</span></div>${state.visits.map(v=>`<div class="row between item"><div><small>${label(v.date)} · ${v.id}</small><h3>${E(v.client)}</h3><p>${E(v.service)} · ${v.outcomes?Object.keys(v.outcomes).length+'/'+tasks.length+' task outcomes recorded':'Read assigned plan before starting'} ${badge(v.status)}</p></div><button data-visit="${v.id}">Open visit</button></div>`).join('')}</section>`}
function hoursPage(){const t=totals();return `<div class="section-head"><div class="actions"><button data-week="prev">‹ Previous week</button><button data-week="current">${synthetic?'Demo week':'This week'}</button><button data-week="next">Next week ›</button></div><strong>${label(week)} – ${label(add(week,6))}</strong></div>${stats([['Scheduled',hours(t.planned)+' h','Planned visits, not work completed'],['Reported actual',hours(t.reported)+' h','Gross minutes less unpaid breaks'],['Approved',hours(t.approved)+' h','Independently reviewed time'],['Awaiting review',hours(t.pending)+' h',hours(t.returned)+' h returned for correction']])}<div class="grid two"><section class="card"><div class="section-head"><h2>Weekly time ledger</h2><button data-action="csv">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Date / visit</th><th>Gross</th><th>Break</th><th>Net</th><th>Status</th><th></th></tr></thead><tbody>${t.rows.map(r=>`<tr><td><strong>${label(r.date)}</strong>${E(visit(r.visitId)?.client||'Unlinked record')}<small>${r.id}</small></td><td>${r.gross} min</td><td>${r.break} min</td><td><strong>${hours(net(r))} h</strong></td><td>${badge(r.status)}<small>${E(r.reason)}</small></td><td><button data-time="${r.id}">${r.status==='returned'?'Correct':'View / query'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No time records for this week.</td></tr>'}</tbody></table></div><p class="muted" style="font-size:11px;margin-top:16px">Example: 240 gross minutes − 30 unpaid break minutes = 210 net minutes = 3.5 hours. Weekly records use the actual shift-start date in Toronto. Travel and expenses are separate. Paid hours need payroll confirmation.</p></section><section class="card"><h2>Reported hours by day</h2><div class="bar-chart">${Array.from({length:7},(_,i)=>{const d=add(week,i),n=sum(t.rows.filter(t=>t.date===d),net);return `<div class="bar-col"><strong>${hours(n)}</strong><i style="height:${Math.min(110,n/60*14)}px"></i>${label(d).split(',')[0]}</div>`}).join('')}</div><h3>Missing or incorrect time?</h3><p class="muted" style="margin:12px 0">Keep the original record and explain your correction. Your supervisor or authorized reviewer makes the decision.</p><button data-action="time-help">Ask about a time record</button><div class="banner warn" style="margin:20px 0 0">A PSW cannot approve her own time or release payroll.</div></section></div>`}
function payPage(){return `${stats([['Confirmed rate','Not configured','Requires employment / contractor record'],['Approved time',hours(totals().approved)+' h','Does not confirm wages paid'],['Next payday','Not configured','Requires employer pay cycle'],['Payroll paid','Not connected','No fabricated statement']])}<div class="grid two"><section class="card"><div class="section-head"><h2>My expense & mileage requests</h2><button data-action="expense" class="primary">New request</button></div>${state.expenses.map(x=>`<div class="item"><div class="row between"><strong>${E(x.category)} · ${x.date}</strong>${badge(x.status||'pending')}</div><p>${x.category==='Submitted claim'?'Submitted claim — see team response':x.category==='Mileage'?E(x.amount)+' km — reimbursement rate not configured':'CAD '+Number(x.amount).toFixed(2)} · ${E(x.reason)}</p><small>Evidence reference: ${E(x.evidence)} · demo only</small></div>`).join('')||'<p class="empty">No claims yet. Submit evidence for review; eligibility and rates depend on confirmed policy.</p>'}</section><section class="card"><h2>A question about my pay</h2><p class="muted" style="margin:15px 0">Link your question to the date and time record. The original time record and payroll statement must stay unchanged.</p><button data-action="pay-query">Raise a pay / hours query</button><div class="item"><h3>Pay is not inferred</h3><p>Do not multiply scheduled time by an invented rate. Any future estimate must show the confirmed rate, effective date, deductions and approval state.</p></div></section></div>`}
function availabilityPage(){return `<div class="grid two"><section class="card"><div class="section-head"><h2>My availability preferences</h2><button data-action="availability">Edit preferences</button></div><div class="grid three"><div><small>Days</small><h3>${E(state.available.days)}</h3></div><div><small>Hours</small><h3>${state.available.start&&state.available.end?state.available.start+'–'+state.available.end:'Not configured'}</h3></div><div><small>Preferred area</small><h3>${E(state.available.area)}</h3></div></div><div class="item"><h3>My weekly availability goal</h3><p>${state.goal?state.goal+' hours':'Goal not set'} · ${hours(totals().planned)} scheduled this week</p><button data-action="goal" style="margin-top:12px">Change my goal</button></div><div class="actions"><button data-action="leave">Request time off</button><button data-action="open-work" class="primary">Ask for open work</button></div></section><section class="card"><h2>Requests & decisions</h2>${!synthetic?`<button data-action="native-availability">Record actual availability / leave</button><div class="item"><h3>Saved staffing windows</h3>${meta.windows.map(w=>`<p>${E(w.kind)} · ${E(w.starts_at)} to ${E(w.ends_at)} · ${E(w.status)}</p>`).join('')||'<p>No availability or leave windows recorded.</p>'}</div>`:''}${state.requests.map(r=>`<div class="item"><div class="row between"><strong>${E(r.type)}</strong>${badge(r.status)}</div><p>${E(r.detail)}</p><small>${E(r.owner)} · reference ${E(r.id)}</small></div>`).join('')||'<p class="empty">No requests yet. Pending leave does not change assigned visits.</p>'}</section></div>`}
function messagesPage(){return `<div class="grid two"><section class="card"><div class="section-head"><h2>Team updates & handovers</h2><button data-action="help" class="primary">New message</button></div>${state.messages.map(m=>`<div class="item"><div class="row between"><h3>${E(m.subject)}</h3>${badge(m.status)}</div><small>${E(m.from)} · ${E(m.at)}</small><p>${E(m.text)}</p>${m.status==='unread'?`<button data-ack="${m.id}" style="margin-top:12px">Acknowledge update</button>`:'<small>Saved locally; external delivery not connected.</small>'}</div>`).join('')}</section><section class="card"><h2>Requests that need a response</h2>${state.requests.map(r=>`<div class="item"><strong>${E(r.type)}</strong><p>${E(r.detail)}</p><small>Owner: ${E(r.owner)} · ${badge(r.status)}</small></div>`).join('')||'<p class="empty">No open requests.</p>'}<div class="banner warn" style="margin-top:20px"><strong>Urgent safety issue?</strong><p>Follow the emergency plan and contact emergency services directly if there is immediate danger. A saved form is not an emergency alert.</p></div></section></div>`}
function profilePage(){return `<div class="grid two"><section class="card"><div class="section-head"><h2>${E(NAME)} · ${E(meta.profile.role.toUpperCase())}</h2><span class="badge blue">${synthetic?'Marked demo profile':'My account profile'}</span></div><p>Preferred area: ${E(state.available.area)}</p><p>Organization: ${E(meta.identity.organization)}</p><a href="/tenant-dashboard?enable-semantics=true" data-cy="tenant-task-workspace-nav">My work & tasks</a><a href="/success">Account and security</a><p class="muted">Name and role come from your signed-in account. Use the account page for phone verification and security. No verification result is fabricated.</p><div class="item"><h3>My training & document readiness</h3>${(synthetic?[['Orientation','Synthetic sample','approved'],['Organization clearance','Synthetic sample','approved'],['Care plan','Sample review needed','returned']]:[['Provider approval',meta.profile.profileApproved?'Approved':'Missing',meta.profile.profileApproved?'approved':'returned'],['Induction',meta.profile.induction?'Completed':'Missing',meta.profile.induction?'approved':'returned'],['Clearance',meta.profile.clearanceStatus+(meta.profile.clearanceExpires?' · '+meta.profile.clearanceExpires:''),meta.profile.qualified?'approved':'returned']]).map(([n,d,s])=>`<div class="row between item"><span>${n}<br><small>${d}</small></span>${badge(s)}</div>`).join('')}</div><button data-action="document">Ask about a missing document</button></section><section class="card"><h2>My information & access</h2><div class="item"><h3>Assigned care only</h3><p>Live PSWs see their own assigned records, not the entire coordinator roster or another tenant’s patients.</p></div><div class="item"><h3>Account security</h3><p>Existing sign-in, session, phone verification and recovery flows are reused during integration.</p><button data-action="account-help" style="margin-top:10px">Get account help</button></div><div class="item"><h3>Storage & connection</h3><p>Integrated: saved in this browser. Live release: show database-confirmed save, request ID, retry and conflict states. Do not claim unsaved data is synced.</p></div></section></div>`}
function questionsPage(){const filtered=PLAN.questions.filter(q=>(qaGroup==='all'||q.group===qaGroup)&&[q.question,q.answer,q.id].join(' ').toLowerCase().includes(qaFilter.toLowerCase()));return `<div class="card"><div class="section-head"><h2>${PLAN.questionCount} PSW questions</h2><button data-action="questions-export">Download questions & map</button></div><div class="fields"><label>Search questions<input id="qa-search" type="search" value="${E(qaFilter)}" placeholder="Hours, break, client, consent…"></label><label>Question group<select id="qa-group"><option value="all">All groups</option>${[...new Set(PLAN.questions.map(q=>q.group))].map(g=>`<option ${g===qaGroup?'selected':''}>${g}</option>`).join('')}</select></label></div><div id="qa-results" style="margin-top:20px">${qaRows(filtered)}</div></div>`}
function qaRows(rows){return rows.map(q=>`<details class="qa"><summary><span class="code">${q.id}</span> · ${E(q.question)}</summary><div class="answer"><p>${E(q.answer)}</p><p class="code">${q.task} → psw_personal_${q.screen} → ${q.workflow}</p><button data-go="${q.screen}" style="margin-top:12px">Open the matching screen →</button></div></details>`).join('')||'<p class="empty">No matching questions.</p>'}
function guidePage(){return `<div class="grid two"><section class="card"><h2>Your first shift in six steps</h2>${[['today','Prepare your day','Read today’s visits and team updates.'],['visit','Read the plan & accept','Check readiness, current plan and client preferences.'],['visit','Start with consent','Confirm consent before starting the visit record.'],['visit','Record task outcomes','Use Completed, Declined or Held. Explain unresolved needs.'],['hours','Submit actual time','Report gross minutes and unpaid breaks. Corrections need a reason.'],['messages','Close the loop','Read review feedback, provide handover and follow up on concerns.']].map(([p,t,d],i)=>`<div class="step"><span class="checkmark">${i+1}</span><div><h3>${t}</h3><p class="muted">${d}</p><button class="linkbutton" data-go="${p}">Open this step →</button></div></div>`).join('')}</section><section class="card"><h2>Your daily check</h2><div class="checklist" style="margin:20px 0">${['Check any schedule changes','Read assigned plan and handover','Confirm consent at the visit','Complete or resolve each task','Submit note and actual time','Read correction or review requests'].map(t=>`<label class="checkbox"><input type="checkbox">${t}</label>`).join('')}</div><p class="muted">This checklist is a learning aid. It does not submit clinical records or time.</p><button data-go="questions" style="margin-top:18px">Read every PSW question</button></section></div>`}
function planPage(){return `<section class="card board-plan"><h2>1. Questions → 2. Tasks → 3. HTML → 4. Integrated release</h2><p style="margin-top:12px">Integrated worker workspace. The release registers the screen, workflow and API catalogue. Live clinical actions use existing care APIs; demo actions write only marked synthetic data.</p></section><div class="card" style="margin-top:20px"><div class="section-head"><h2>Screen & workflow registration proposal</h2><button data-action="questions-export">Export full specification</button></div><div class="table-wrap"><table><thead><tr><th>Task</th><th>Screen</th><th>Worker need</th><th>Workflow</th><th>State</th></tr></thead><tbody>${PLAN.screens.map(s=>`<tr><td>${s.task}</td><td><span class="code">${s.code}</span><small>${s.proposedRoute}</small></td><td><button class="linkbutton" data-go="${s.previewView}">${E(s.title)} →</button></td><td>${s.workflow}</td><td>Integrated</td></tr>`).join('')}</tbody></table></div></div><div class="grid two" style="margin-top:20px"><section class="card"><h2>Integration and verification tasks</h2><p class="muted">${PLAN.tasks.length} coded tasks, including the screen map above. Reuse shared clients and the current care APIs; production governance remains the registry authority.</p>${PLAN.integrationTasks.map(t=>`<div class="item"><span class="code">${t.code}</span><h3>${E(t.title)}</h3><p>${E(t.status.replaceAll('_',' '))}</p></div>`).join('')}</section><section class="card"><h2>What must be registered and tested</h2>${['Reuse existing care screen/API contracts where they already exist; avoid duplicate registry entries.','Register new personal screen sections, controls, test IDs, resource strings and role grants.','Map each question and task to a workflow, owner, allowed action and acceptance check.','Implement scoped weekly time totals, correction requests and independent review; do not infer payroll.','Register API request/response schemas, immutable audit events and save failure states.','Verify login → UI action → API → database → reload, plus denied roles, foreign tenants and stale versions.','Publish only after these checks pass. Mark missing payroll or delivery integrations honestly.'].map((t,i)=>`<div class="step"><span class="checkmark">${i+1}</span><p>${t}</p></div>`).join('')}<h3 style="margin-top:20px">Saved workspace activity</h3>${state.audit.slice(0,8).map(a=>`<div class="item"><strong>${E(a.action)}</strong><p>${E(a.detail)}<br>${E(a.at)}</p></div>`).join('')||'<p class="muted">Actions you try will appear here.</p>'}</section></div>`}
function openVisit(id){const v=visit(id);if(!synthetic){if(!v?.caseId)return toast('No authorized care case is available.');void nativeRecord(v.caseId);return;}if(!v)throw Error('Visit not found');const canStart=['accepted'].includes(v.status),active=v.status==='in_progress';const d=modal(v.client+' · '+v.id,`<div class="row">${badge(v.status)}<span>${label(v.date)} · ${clock(v.start)} · ${v.duration} min planned</span></div><p><strong>Assigned provider: ${E(NAME)} · ${E(meta.profile.role.toUpperCase())}</strong><br>${E(v.service)} · ${E(v.area)} · fictional location</p><div class="banner ${v.ready===false?'warn':''}"><strong>${v.ready===false?'Plan approval is missing — care cannot start':'Sample assigned plan CP-204 · version 3'}</strong><p>Use a calm introduction. Ask the person’s preferences. Follow assigned support tasks. No medication or controlled-act authority is granted by this preview.</p></div>${v.status==='assigned'&&v.ready!==false?'<label class="checkbox"><input type="checkbox" name="read" required>I read this assigned plan and understand my tasks.</label>':''}${canStart?'<label class="checkbox"><input type="checkbox" name="consent" required>The demo client consented to this visit and its assigned support tasks.</label>':''}${active||['submitted','reviewed'].includes(v.status)?`<p class="muted">${v.clockIn?'Demo clock started '+new Date(v.clockIn).toLocaleTimeString('en-CA',{timeZone:'America/Toronto'})+' · '+Math.floor(((v.clockOut||Date.now())-v.clockIn)/60000)+' elapsed minutes. Reported minutes remain separately reviewed.':''}</p><h3>Assigned tasks</h3>${tasks.map((t,i)=>`<div class="task"><span>${t}</span>${select('task'+i,'Task '+(i+1)+' outcome',[['','Choose outcome'],['done','Completed'],['declined','Declined'],['held','Held / follow-up']],v.outcomes?.[i]||'')}</div>`).join('')}${text('note','Factual visit note & handover',v.note||'')}${active?`<div class="fields">${field('gross','Reported gross work minutes',v.clockIn?Math.floor((Date.now()-v.clockIn)/60000):0,'number','min="0" max="720" step="1"')}${field('break','Actual unpaid break minutes',0,'number','min="0" max="720" step="1"')}${text('timeReason','Time evidence / reason (required)')}</div><p class="muted">The real elapsed demo clock may be less than one minute. Planned duration is not automatically counted as worked time. Any manually reported time is awaiting review.</p>`:''}`:''}${v.status==='assigned'&&v.ready===false?'<button type="button" data-blocked>Ask supervisor to review plan</button>':''}${['assigned','accepted','in_progress'].includes(v.status)?'<button type="button" data-report>Report concern / no access / delay</button>':''}${['submitted','reviewed'].includes(v.status)?'<p class="muted">Submitted records are read-only in this worker view. Use an amendment request to preserve the original.</p><button type="button" data-amend>Request an amendment</button>':''}`,active?'Submit visit & reported time':v.status==='assigned'&&v.ready!==false?'Accept assigned visit':canStart?'Start demo visit':null,x=>{if(v.ready===false)throw Error('Plan readiness is missing');if(v.status==='assigned'){v.status='accepted';save('Visit accepted',id)}else if(canStart){if(state.visits.some(a=>a.status==='in_progress'))throw Error('Finish the active visit before starting another.');v.status='in_progress';v.clockIn=Date.now();save('Demo visit started',id)}else if(active){for(let i=0;i<tasks.length;i++)if(!['done','declined','held'].includes(x['task'+i]))throw Error('Record an outcome for every assigned task.');if(x.note.trim().length<10||x.timeReason.trim().length<10)throw Error('Record a meaningful note and time evidence.');const gross=Number(x.gross),br=Number(x.break);if(!Number.isInteger(gross)||!Number.isInteger(br)||gross<0||gross>720||br<0||br>gross)throw Error('Break minutes must be between zero and the reported gross minutes.');v.outcomes=Object.fromEntries(tasks.map((_,i)=>[i,x['task'+i]]));v.note=x.note.trim();v.status='submitted';v.clockOut=Date.now();state.time.push({id:'TM-'+uid().slice(0,8),visitId:id,date:v.date,gross,break:br,status:'pending',reason:x.timeReason,history:[]});save('Visit and time submitted',id+' · '+net(state.time.at(-1))+' net minutes')}});d.querySelector('[data-report]')?.addEventListener('click',()=>{d.remove();issueModal(id)});d.querySelector('[data-blocked]')?.addEventListener('click',()=>{d.remove();requestModal('Plan review request',id+' · updated plan needs independent review.','Assigned supervisor')});d.querySelector('[data-amend]')?.addEventListener('click',()=>{d.remove();requestModal('Note amendment',id+' · explain the factual correction.','Assigned supervisor')});if(!active){d.querySelectorAll('select[name^=task],textarea[name=note]').forEach(e=>e.disabled=true)}}
function requestModal(type,prefill='',owner='Demo coordinator'){modal(type,field('subject','Subject',type)+text('detail',synthetic?'Synthetic practice details':'Work details — no health information',prefill), 'Save request',x=>{if(x.detail.trim().length<10)throw Error('Please add useful details.');state.requests.unshift({id:'REQ-'+uid().slice(0,8),type,detail:x.detail,owner,status:'requested'});save(type+' requested',x.subject)})}
function issueModal(id){if(!synthetic){const v=visit(id);void nativeRecord(v?.caseId);return;}const d=modal('Visit issue · '+id,select('type','Issue',[['Delay','Running late'],['No access','Client not home / no access'],['Coverage','Cannot attend / need coverage'],['Concern','Safety or care concern']],'Delay')+text('detail','Facts, immediate action and help needed')+'<div class="banner warn">This does not send an emergency alert. Follow the real emergency process for immediate danger.</div>', 'Record issue',x=>{state.requests.unshift({id:'ISS-'+uid().slice(0,8),type:x.type,detail:id+' · '+x.detail,owner:x.type==='Concern'?'Assigned supervisor':'Demo coordinator',status:'requested'});save('Visit issue recorded',id+' · '+x.type)})}
function timeModal(id){if(!synthetic){void nativeRecord(id,'timesheets');return;}const t=state.time.find(t=>t.id===id);if(!t)return;const editable=t.status==='returned';modal('Time record · '+id,`<p><strong>${E(visit(t.visitId)?.client)}</strong> · ${label(t.date)}<br>${badge(t.status)} · ${E(t.reason)}</p>${editable?`<div class="fields">${field('gross','Corrected gross work minutes',t.gross,'number','min="0" max="720" step="1"')}${field('break','Actual unpaid break minutes',t.break,'number','min="0" max="720" step="1"')}</div>${text('reason','Correction evidence and reason')}`:`<p>${t.gross} gross − ${t.break} unpaid break = <strong>${net(t)} net minutes (${hours(net(t))} h)</strong></p>${text('reason','Explain your query or requested correction')}`}<p class="muted">The original record is retained. A PSW cannot approve her own time.</p>${t.history.map(h=>`<p class="muted">Previous: ${h.gross} gross / ${h.break} break · ${E(h.status)} · ${E(h.reason)}</p>`).join('')}`,editable?'Resubmit for time review':'Request review / correction',x=>{if(x.reason.trim().length<10)throw Error('Add a meaningful reason.');if(editable){const g=Number(x.gross),b=Number(x.break);if(!Number.isInteger(g)||!Number.isInteger(b)||g<0||g>720||b<0||b>g)throw Error('Invalid work or break minutes.');t.history.push({gross:t.gross,break:t.break,status:t.status,reason:t.reason,at:new Date().toISOString()});Object.assign(t,{gross:g,break:b,status:'pending',reason:x.reason});save('Time correction resubmitted',id)}else{state.requests.unshift({id:'REQ-'+uid().slice(0,8),type:'Time correction query',detail:id+' · '+x.reason,owner:'Authorized time reviewer',status:'requested'});save('Time review requested',id)}})}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function action(id){if(id==='refresh')return void reload();if(id==='demo_load')return void commit('demo_load',{});if(!synthetic&&['leave','native-availability'].includes(id))return void nativeRecord(undefined,'staffing');if(!synthetic&&id==='open-work')return requestModal('Open work request','Available dates, hours, service areas and preferences: ','Tenant operations');if(id==='help')return modal('Contact my team',select('to',synthetic?'Intended demo team member':'Work request queue',synthetic?[['Supervisor','Maya · demo supervisor'],['Coordinator','Rina · demo coordinator']]:[['Tenant operations','Tenant operations · saved work requests']],synthetic?'Coordinator':'Tenant operations')+field('subject','Subject')+text('message',synthetic?'Synthetic practice message':'Work message — no health information')+'<p class="muted">Saves a request in the tenant operations queue. For clinical handovers, open the assigned care record. No external message or emergency alert is sent.</p>','Save local message',x=>{state.messages.unshift({id:'MSG-'+uid().slice(0,8),subject:x.subject,text:x.message,from:'You → '+x.to,status:'saved locally',at:BASE});save('Local message saved',x.subject)});
if(id==='goal')return modal('My weekly availability goal',field('goal','Hours I would like to be available',state.goal,'number','min="1" max="80" step="0.5"')+'<p class="muted">This is a preference, not guaranteed hours, an employment commitment or a wage calculation.</p>','Save my goal',x=>{state.goal=Number(x.goal);save('Availability goal updated',state.goal+' hours')});
if(id==='availability')return modal('My availability preferences',`<div class="fields">${field('days','Available days',state.available.days)}${field('area','Preferred area',state.available.area)}${field('start','Start time',state.available.start,'time')}${field('end','End time',state.available.end,'time')}</div>`,'Save preferences',x=>{if(x.end<=x.start)throw Error('End time must be after start time.');state.available=x;save('Availability preferences saved',x.days+' · '+x.start+'–'+x.end)});
if(id==='leave')return modal('Request time off',`<div class="fields">${field('from','First date','2026-11-09','date')}${field('to','Last date','2026-11-09','date')}${text('reason','Reason / coverage details')}</div><p class="muted">This is pending until the authorized team reviews coverage. Existing assignments are not cancelled.</p>`,'Submit leave request',x=>{if(x.to<x.from)throw Error('Last date must not be before first date.');state.requests.unshift({id:'LEAVE-'+uid().slice(0,8),type:'Leave request',detail:x.from+' to '+x.to+' · '+x.reason,owner:'Demo coordinator',status:'requested'});save('Leave requested',x.from+' → '+x.to)});
if(id==='open-work')return modal('Request suitable open work','<p>Fictional opportunity · Fri Oct 30 · 15:00–16:30 · West Hamilton · personal support · 1.5 hours planned</p>'+text('reason','Why this fits my availability')+'<p class="muted">The live system must check availability, overlap, travel, eligibility and current clearance. A request does not assign you or add worked hours.</p>','Request this opportunity',x=>{if(state.requests.some(r=>r.type==='Open work request'))throw Error('You already requested this demo opportunity.');state.requests.unshift({id:'OPEN-'+uid().slice(0,8),type:'Open work request',detail:'Oct 30 · 15:00–16:30 · '+x.reason,owner:'Demo scheduler',status:'requested'});save('Open work requested','Fictional Friday opportunity')});
if(id==='expense')return modal('Expense / mileage request',`<div class="fields">${select('category','Category',[['Mileage','Mileage (km)'],['Expense','Expense (CAD)']],'Mileage')}${field('date','Date',BASE,'date')}${field('amount','Distance (km) or amount (CAD)','','number','min="0.01" max="10000" step="0.01"')}${field('evidence','Receipt / evidence reference')}${text('reason','Purpose and related visit')}</div><p class="muted">No files are uploaded. Reimbursement policy and rate are not configured.</p>`,'Submit for review',x=>{state.expenses.unshift({...x,id:uid(),status:'pending'});save('Expense request submitted',x.category+' · '+x.date)});
if(id==='time-help')return requestModal('Time record query','Record ID and dated work details: ','Authorized time reviewer');if(id==='pay-query')return requestModal('Pay / hours query','Date, time record or statement reference and question: ','Payroll / administration');if(id==='document')return requestModal('Document readiness query','','Authorized clearance reviewer');if(id==='account-help')return requestModal('Account help','Describe the sign-in or verification issue without including passwords or verification codes.','Account support');if(id==='export')return download('PrimeCare_PSW_Personal_Demo.json',JSON.stringify({synthetic:true,storage:'PostgreSQL',dataset:meta.dataset,state},null,2));if(id==='questions-export')return download('PrimeCare_PSW_Questions_Tasks_Registry.json',JSON.stringify(PLAN,null,2));if(id==='csv'){const cell=x=>{const raw=String(x),safe=/^[=+\-@\t\r]/.test(raw)?"'"+raw:raw;return '"'+safe.replaceAll('"','""')+'"'},rows=[['Date','Record','Visit','Client','Gross minutes','Unpaid break minutes','Net hours','Status','Reason'],...totals().rows.map(t=>[t.date,t.id,t.visitId,visit(t.visitId)?.client,t.gross,t.break,(net(t)/60).toFixed(2),t.status,t.reason])];return download('PSW_Weekly_Hours_'+week+'.csv',rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};if(id==='reset')return modal('Clear marked demo data?', '<p>This clears only the marked synthetic personal workspace. Real visits, live time records and audit history are preserved. Load demo data later if you want the sample records again.</p>','Clear demo data',()=>{save('Practice reset','Synthetic browser-local data only')})}
function bind(){app.querySelectorAll('[data-action]').forEach(e=>e.setAttribute('data-cy','psw-personal-'+e.dataset.action));app.querySelectorAll('[data-go]').forEach(e=>e.setAttribute('data-cy','psw-personal-nav-'+e.dataset.go));app.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));app.querySelector('[data-menu]').onclick=e=>{const side=app.querySelector('.side');side.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(side.classList.contains('open')))};app.querySelectorAll('[data-visit]').forEach(b=>{b.setAttribute('data-cy','psw-personal-visit-open');b.onclick=()=>openVisit(b.dataset.visit)});app.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>timeModal(b.dataset.time));app.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>issueModal(b.dataset.issue));app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;draw()});app.querySelector('#schedule-date')?.addEventListener('change',e=>{if(!e.target.value)return toast('Choose a valid schedule date.');selectedDate=e.target.value;const d=new Date(selectedDate+'T12:00:00Z').getUTCDay();week=add(selectedDate,-(d===0?6:d-1));void reload()});app.querySelectorAll('[data-week]').forEach(b=>{b.setAttribute('data-cy','psw-personal-week-'+b.dataset.week);b.onclick=()=>{week=b.dataset.week==='current'?MON:add(week,b.dataset.week==='prev'?-7:7);void reload()}});app.querySelectorAll('[data-ack]').forEach(b=>b.onclick=()=>{const m=state.messages.find(m=>m.id===b.dataset.ack);m.status='acknowledged';save('Update acknowledged',m.id)});app.querySelector('#qa-search')?.addEventListener('input',e=>{qaFilter=e.target.value;refreshQA()});app.querySelector('#qa-group')?.addEventListener('change',e=>{qaGroup=e.target.value;refreshQA()})}
function refreshQA(){const rows=PLAN.questions.filter(q=>(qaGroup==='all'||q.group===qaGroup)&&[q.question,q.answer,q.id].join(' ').toLowerCase().includes(qaFilter.toLowerCase()));app.querySelector('#qa-results').innerHTML=qaRows(rows);app.querySelectorAll('#qa-results [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}root.__pswPersonalCleanup?.();const syncHash=()=>{if(sessionStorage.getItem('primecare_session')!==api.token||!root.querySelector('[data-cy^=\"screen-psw-personal-\"]'))return;const next=location.hash.slice(1)||'today';if(next!==page){page=next;draw();}};window.addEventListener('hashchange',syncHash);root.__pswPersonalCleanup=()=>window.removeEventListener('hashchange',syncHash);draw();

}
